namespace FoolLauncher {
 public static class CatalogTests {
  sealed class Progress:IProgress<Update>{readonly bool print;public Progress(bool value=false){print=value;}public void Report(Update u){if(print&&u.Message!=null&&!u.Message.StartsWith("正在下载"))Console.WriteLine(u.Message);}}
  static void Assert(bool value,string error){if(!value)throw new Exception(error);}
  static string Serialize(object o){return new JavaScriptSerializer().Serialize(o);}
  static byte[] Jar(string id,string version){using(var memory=new MemoryStream()){using(var zip=new ZipArchive(memory,ZipArchiveMode.Create,true)){using(var w=new StreamWriter(zip.CreateEntry("fabric.mod.json").Open()))w.Write(Serialize(new{id=id,version=version}));using(var w=new StreamWriter(zip.CreateEntry("version.txt").Open()))w.Write(version);}return memory.ToArray();}}
  static CatalogArtifact Artifact(string name,byte[] data){using(var hash=SHA512.Create())return new CatalogArtifact{Name=name,Size=data.Length,Url="https://cdn.modrinth.com/data/fixture/versions/test/"+name,Hashes=new Dictionary<string,string>{{"sha512",BitConverter.ToString(hash.ComputeHash(data)).Replace("-","").ToLowerInvariant()}}};}
  static CatalogVersion Version(string project,string version,CatalogArtifact file,params CatalogDependency[] deps){return new CatalogVersion{Source="modrinth",ProjectId=project,Id=version,Name=project+version,Number=version,GameVersions=new[]{"1.21.1"},Loaders=new[]{"fabric"},File=file,Channel="release",Dependencies=deps};}
  static object Mr(CatalogVersion v){return new{id=v.Id,project_id=v.ProjectId,name=v.Name,version_number=v.Number,version_type=v.Channel,game_versions=v.GameVersions,loaders=v.Loaders,files=new[]{new{filename=v.File.Name,url=v.File.Url,size=v.File.Size,hashes=v.File.Hashes,primary=true}},dependencies=(v.Dependencies??new CatalogDependency[0]).Select(d=>new{project_id=d.Project,version_id=d.Version,dependency_type=d.Type}).ToArray()};}
  static Instance Fixture(PackService service,string id,byte[] old=null){
   var instance=new Instance{Id=id,Name=id,Minecraft="1.21.1",Loader="fabric-loader 0.16.14",Ready=true};Directory.CreateDirectory(Path.Combine(service.Game(instance),"mods"));var files=new List<PackFile>();
   if(old!=null){File.WriteAllBytes(Path.Combine(service.Game(instance),"mods","old-readable-name.jar"),old);var a=Artifact("old-readable-name.jar",old);files.Add(new PackFile{path="mods/"+a.Name,fileSize=a.Size,hashes=a.Hashes,downloads=new[]{a.Url}});}
   instance.FileCount=files.Count;Json.Write(Path.Combine(service.Folder(instance),"pack-index.json"),new PackIndex{game="minecraft",formatVersion=1,name=id,versionId="fixture",dependencies=new Dictionary<string,string>{{"minecraft","1.21.1"},{"fabric-loader","0.16.14"}},files=files.ToArray()});Json.Write(Path.Combine(service.Folder(instance),"launcher-instance.json"),instance);return instance;
  }
  static Dictionary<string,string> Snapshot(PackService service,Instance i){string root=service.Folder(i);return Directory.GetFiles(root,"*",SearchOption.AllDirectories).Where(f=>!f.Contains("mod-backups")&&!f.EndsWith(".lock")).ToDictionary(f=>f.Substring(root.Length+1),LauncherUpdateCore.HashFile);}
  static void Same(PackService service,Instance i,Dictionary<string,string> before){var after=Snapshot(service,i);Assert(before.Count==after.Count&&before.All(p=>after.ContainsKey(p.Key)&&after[p.Key]==p.Value),"Mod transaction failed to restore original files");}
  static void Reject(Action action,string message){bool rejected=false;try{action();}catch(IOException){rejected=true;}catch(InvalidDataException){rejected=true;}catch(OperationCanceledException){rejected=true;}Assert(rejected,message);}
  public static void Run(string parent){
   var service=new PackService(Path.Combine(parent,"catalog"));byte[] old=Jar("fixture_mod","1"),latest=Jar("fixture_mod","2"),dep=Jar("fixture_dependency","1");var f=Artifact("fixture-v2.jar",latest);var d=Artifact("dependency.jar",dep);var dependency=Version("dep","depv1",d);var main=Version("main","mainv2",f,new CatalogDependency{Project="dep",Version="depv1",Type="required"},new CatalogDependency{Project="optional",Type="optional"});
   var catalog=new CatalogService((url,ct)=>{ct.ThrowIfCancellationRequested();if(url.EndsWith("/version/depv1"))return Task.FromResult(Serialize(Mr(dependency)));if(url.EndsWith("/version/mainv2"))return Task.FromResult(Serialize(Mr(main)));throw new IOException("Unexpected fixture request "+url);});
   Func<CatalogArtifact,string,string,IProgress<Update>,CancellationToken,Task> download=(a,path,kind,progress,ct)=>{ct.ThrowIfCancellationRequested();File.WriteAllBytes(path,a.Name==d.Name?dep:latest);return Task.FromResult(0);};var installer=new CatalogInstaller(service,catalog,download);
   var selected=Fixture(service,"selected",old);var other=Fixture(service,"other",old);var untouched=Snapshot(service,other);var result=installer.Install(ModTarget.Capture(service,selected),main,new Progress(),CancellationToken.None).GetAwaiter().GetResult();
   Same(service,other,untouched);Assert(result.Files==2&&result.Dependencies==1&&result.Replaced==1,"Required dependency/replacement plan is wrong");Assert(!File.Exists(Path.Combine(service.Game(selected),"mods","old-readable-name.jar")),"Old mod was retained alongside new version");Assert(service.Index(selected).files.Length==2&&service.Repair(selected,new Progress(),CancellationToken.None).GetAwaiter().GetResult()==0,"Repair resurrected replaced mod or ignored newly installed file");
   var again=installer.Install(ModTarget.Capture(service,selected),main,new Progress(),CancellationToken.None).GetAwaiter().GetResult();Assert(again.Files==0&&Directory.GetFiles(Path.Combine(service.Game(selected),"mods"),"*.jar").Length==2,"Reinstall created duplicate mods");
   for(int step=1;step<=6;step++){var i=Fixture(service,"rollback-"+step,old);var before=Snapshot(service,i);int fail=step;Reject(()=>installer.Install(ModTarget.Capture(service,i),main,new Progress(),CancellationToken.None,n=>{if(n==fail)throw new IOException("Injected failure");}).GetAwaiter().GetResult(),"Injected failure did not propagate");Same(service,i,before);}
   var locked=Fixture(service,"locked",old);var lockedBefore=Snapshot(service,locked);using(var hold=File.Open(Path.Combine(service.Game(locked),"mods","old-readable-name.jar"),FileMode.Open,FileAccess.Read,FileShare.Read))Reject(()=>installer.Install(ModTarget.Capture(service,locked),main,new Progress(),CancellationToken.None).GetAwaiter().GetResult(),"Locked mod accepted");Same(service,locked,lockedBefore);
   var cancelled=Fixture(service,"cancelled",old);var cancelledBefore=Snapshot(service,cancelled);using(var c=new CancellationTokenSource())Reject(()=>installer.Install(ModTarget.Capture(service,cancelled),main,new Progress(),c.Token,n=>{if(n==2)c.Cancel();}).GetAwaiter().GetResult(),"Mid-commit cancellation did not roll back");Same(service,cancelled,cancelledBefore);
   var stale=Fixture(service,"stale",old);var captured=ModTarget.Capture(service,stale);File.AppendAllText(Path.Combine(service.Folder(stale),"pack-index.json")," ");Reject(()=>installer.Install(captured,main,new Progress(),CancellationToken.None).GetAwaiter().GetResult(),"Changed target accepted");
   var wrong=Version("wrong","v1",f);wrong.Loaders=new[]{"forge"};Reject(()=>installer.Install(ModTarget.Capture(service,other),wrong,new Progress(),CancellationToken.None).GetAwaiter().GetResult(),"Wrong loader installed");wrong.Loaders=new[]{"fabric"};wrong.GameVersions=new[]{"1.20.1"};Reject(()=>installer.Resolve(ModTarget.Capture(service,other),wrong,CancellationToken.None).GetAwaiter().GetResult(),"Wrong Minecraft version accepted");Same(service,other,untouched);
   var blocked=new CatalogInstaller(service,catalog,download,()=>true);Reject(()=>blocked.Install(ModTarget.Capture(service,other),main,new Progress(),CancellationToken.None).GetAwaiter().GetResult(),"Game-started-before-commit guard ignored");Same(service,other,untouched);
   var corrupt=new CatalogInstaller(service,catalog,(a,path,kind,p,ct)=>{File.WriteAllText(path,"tampered");return Task.FromResult(0);});Reject(()=>corrupt.Install(ModTarget.Capture(service,other),main,new Progress(),CancellationToken.None).GetAwaiter().GetResult(),"Corrupt CDN bytes installed");Same(service,other,untouched);
   var query=new CatalogQuery{Kind="mod",Game="1.21.1",Loader="fabric",Text="a&b",Page=2};string address=Uri.UnescapeDataString(CatalogService.SearchAddress(query,"modrinth"));Assert(address.Contains("offset=40")&&address.Contains("versions:1.21.1")&&address.Contains("categories:fabric")&&address.Contains("project_type:mod"),"Provider search facets/pagination mismatch");
   string cf=CatalogService.SearchAddress(query,"curseforge");Assert(cf.Contains("classId=6")&&cf.Contains("modLoaderType=4")&&cf.Contains("gameVersion=1.21.1")&&cf.Contains("a%26b"),"CurseForge filter encoding failed");
   var partial=new CatalogService((url,ct)=>{if(url.StartsWith("cf:"))throw new IOException("Fixture offline source");return Task.FromResult(Serialize(new{hits=new[]{new{project_id="main",slug="fixture",title="Fixture",project_type="mod"}},total_hits=1}));});var found=partial.Search(new CatalogQuery(),CancellationToken.None).GetAwaiter().GetResult();Assert(found.Projects.Length==1&&found.Warning.Contains("curseforge"),"One failing provider hid the other source");
   var mismatch=new CatalogService((url,ct)=>Task.FromResult(Serialize(Mr(main))));Reject(()=>mismatch.Version("modrinth","main","other-version",CancellationToken.None).GetAwaiter().GetResult(),"Pinned version ID mismatch accepted");
   foreach(string name in new[]{"../escape.jar","C:/mod.jar","mod.jar:ads","CON.jar"}){var bad=Artifact(name,latest);Reject(()=>CatalogNetwork.Validate(bad,"mod"),"Unsafe download filename accepted");}
   foreach(string url in new[]{"http://cdn.modrinth.com/test.jar","https://localhost/test.jar","https://127.0.0.1/test.jar","https://cdn.modrinth.com.evil.test/a.jar","https://user:pass@cdn.modrinth.com/a.jar"}){var bad=Artifact("safe.jar",latest);bad.Url=url;Reject(()=>CatalogNetwork.Validate(bad,"mod"),"Untrusted download source accepted");}
   Console.WriteLine("PASS: selected-pack-only mod installation, required dependencies, compatibility, old-JAR identity replacement, manifest repair persistence, duplicate avoidance, six-point rollback, cancellation, lock/game/target guards, hash/URL/path/version rejection, dual-source filtering and partial failure.");
  }
  public static async Task<int> Live(string root){
   root=Path.GetFullPath(root);Directory.CreateDirectory(root);root=Path.Combine(root,"live-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Console.WriteLine("LIVE_ROOT="+root);var service=new PackService(root);var api=new CatalogService();var installer=new CatalogInstaller(service,api);var selected=Fixture(service,"selected");var other=Fixture(service,"untouched",Jar("sentinel","1"));var before=Snapshot(service,other);var progress=new Progress(true);
   foreach(var item in new[]{new{Source="modrinth",Query="modmenu",Slug="modmenu"},new{Source="curseforge",Query="Jade",Slug="jade"}}){var search=await api.Search(new CatalogQuery{Source=item.Source,Kind="mod",Text=item.Query,Game="1.21.1",Loader="fabric"},CancellationToken.None);var project=search.Projects.FirstOrDefault(p=>p.Slug==item.Slug);Assert(project!=null,"Live provider search failed: "+item.Source+" "+search.Warning);var versions=await api.Versions(project,"1.21.1","fabric",0,CancellationToken.None);var v=versions.FirstOrDefault(x=>x.Channel=="release")??versions.FirstOrDefault();Assert(v!=null,"No live compatible version: "+project.Name);v=await api.Version(v.Source,v.ProjectId,v.Id,CancellationToken.None);var installed=await installer.Install(ModTarget.Capture(service,selected),v,progress,CancellationToken.None);Same(service,other,before);Assert(await service.Repair(selected,progress,CancellationToken.None)==0,"Live repair did not preserve catalog mods");Console.WriteLine("LIVE_MOD_PASS="+project.Name+" SOURCE="+item.Source+" FILES="+installed.Files+" DEPENDENCIES="+installed.Dependencies);}
   var packs=await api.Search(new CatalogQuery{Source="modrinth",Kind="modpack",Text="adrenaline",Game="1.21.1",Loader="fabric"},CancellationToken.None);var pack=packs.Projects.FirstOrDefault(p=>p.Slug=="adrenaline")??packs.Projects.FirstOrDefault();Assert(pack!=null,"Live modpack search failed");var pv=(await api.Versions(pack,"1.21.1","fabric",0,CancellationToken.None)).First();bool visible=false;var added=await installer.InstallPack(pack,pv,progress,i=>{visible=service.List().Any(x=>x.Id==i.Id);},CancellationToken.None);Assert(visible&&service.List().Any(i=>i.Id==added.Id)&&added.Ready,"Downloaded modpack was not added/prepared in library");Same(service,other,before);Console.WriteLine("LIVE_PACK_PASS="+added.Name+" FILES="+added.FileCount);
   Json.Write(Path.Combine(root,"catalog-live-report.json"),new{Passed=true,Modrinth=true,CurseForge=true,ModpackInLibrary=true,UntouchedOtherPack=true,ModFiles=Directory.GetFiles(Path.Combine(service.Game(selected),"mods"),"*.jar").Length,Pack=added.Name});return 0;
  }
 }
